import React from 'react';
import {renderToString} from 'react-dom/server';
import {ThemeProvider} from '@gravity-ui/uikit';
import {ColumnReorderingProvider, Table, useRowSelectionFixedHandler, useTable} from '@gravity-ui/table';
import type {ColumnDef} from '@gravity-ui/table';
import type {ExpandedState, RowSelectionState, ColumnPinningState} from '@gravity-ui/table/tanstack';
import {ORDERS, STATUS_META, groupOrdersByStatus, type OrderRow} from '/home/sandbox/workspace/src/orders';

const getRowId = (row: OrderRow) => row.id;
const getSubRows = (row: OrderRow) => (row.kind === 'group' ? row.orders : undefined);
const cols: ColumnDef<OrderRow>[] = [
  {id: 'select', header: 'S', cell: () => 'sel', size: 48, enableColumnReordering: false},
  {id: 'number', header: 'Заказ', cell: ({row}) => (row.original.kind === 'order' ? row.original.id : null)},
  {id: 'status', header: 'Статус', cell: ({row}) => (row.original.kind === 'order' ? STATUS_META[row.original.status].title : null)},
];
function Probe({expandedInit}: {expandedInit: ExpandedState}) {
  const [rowSelection, setRowSelection] = React.useState<RowSelectionState>({ 'ORD-1001': true });
  const [expanded, setExpanded] = React.useState<ExpandedState>(expandedInit);
  const [columnOrder, setColumnOrder] = React.useState<string[]>(['select', 'number', 'status']);
  const [columnPinning, setColumnPinning] = React.useState<ColumnPinningState>({left: ['select']});
  const data: OrderRow[] = groupOrdersByStatus(ORDERS);
  const handle = useRowSelectionFixedHandler({rowSelection, setRowSelection, tableData: data, getSubRows, getRowId});
  const table = useTable({
    columns: cols, data, getRowId, getSubRows, enableRowSelection: true, enableMultiRowSelection: true, enableExpanding: true,
    state: {rowSelection, expanded, columnOrder, columnPinning},
    onRowSelectionChange: handle, onExpandedChange: setExpanded, onColumnOrderChange: setColumnOrder, onColumnPinningChange: setColumnPinning,
  });
  return (
    <ColumnReorderingProvider table={table} onReorder={({columnOrder: o, columnPinning: p}) => { setColumnOrder(o); setColumnPinning(p); }}>
      <Table table={table} stickyHeader getGroupTitle={(row: any) => (row.original.kind === 'group' ? `${STATUS_META[row.original.status].title} · ${row.original.orders.length}` : null)} getIsGroupHeaderRow={(row: any) => row.original.kind === 'group'} />
    </ColumnReorderingProvider>
  );
}
for (const [label, init] of [['expanded=true', true], ['collapsed={}', {}]] as const) {
  const html = renderToString(<ThemeProvider theme="light"><Probe expandedInit={init as ExpandedState} /></ThemeProvider>);
  const count = (s: string) => html.split(s).length - 1;
  console.log(label, '| groups:', ['Новый', 'В обработке', 'Отправлен', 'Доставлен', 'Отменён'].map((t) => count(t + ' · ')).join(','), '| ORD rows:', count('ORD-'), '| len', html.length);
}
EOF
